19	import type { GalleryState, Item, Mode, Placement, Scene } from '../model/types';
20	import { BACKGROUNDS, MAX_SCENES, type BackgroundAsset } from '../assets/manifest';
21	
22	export type GalleryAction =
23	  | { type: 'create-scene'; backgroundId: string }
24	  | { type: 'select-scene'; sceneId: string }
25	  | { type: 'rename-scene'; sceneId: string; name: string }
26	  | { type: 'delete-scene'; sceneId: string }
27	  | { type: 'set-mode'; mode: Mode }
28	  | { type: 'place-item'; itemId: string; x?: number; y?: number }
29	  | { type: 'move-placement'; placementId: string; x: number; y: number }
30	  | { type: 'resize-placement'; placementId: string; w: number }
