33	  | { type: 'set-item-story'; itemId: string; story: string }
34	  | { type: 'set-item-name'; itemId: string; name: string }
35	  | { type: 'add-item'; name: string; aspectRatio: number; imageSrc: string }
36	  | { type: 'delete-item'; itemId: string }
37	  | { type: 'hydrate-item-image'; itemId: string; imageSrc: string }
38	  | { type: 'set-gallery-name'; name: string };
39	
40	/** 新摆放的默认宽度：占场景图宽的百分比（N2·schema v3；约合中等物件，可再缩放）。 */
