42	
43	/** 单调递增计数 + 时间戳 + 随机后缀，保证同一会话内 id 唯一。 */
44	let idSeq = 0;
45	function newId(prefix: string): string {
46	  idSeq += 1;
47	  return `${prefix}-${Date.now().toString(36)}-${idSeq}-${Math.random().toString(36).slice(2, 7)}`;
48	}
