50	// —— 派生选择器 ——
51	
52	/** 尚未被任何场景占用的背景（背景不可重复的可视化数据源）。 */
53	export function availableBackgrounds(state: GalleryState): BackgroundAsset[] {
54	  const used = new Set(state.scenes.map((s) => s.backgroundId));
55	  return BACKGROUNDS.filter((b) => !used.has(b.id));
56	}
57	
58	/** 还能不能再建场景：仍有未用背景，且未达上限。 */
59	export function canAddScene(state: GalleryState): boolean {
60	  return state.scenes.length < MAX_SCENES && availableBackgrounds(state).length > 0;
61	}
62	
63	/** 当前激活的场景对象（无则 undefined）。 */
64	export function activeScene(state: GalleryState): Scene | undefined {
65	  return state.scenes.find((s) => s.id === state.activeSceneId);
66	}
67	
68	/** 某场景内的摆放，按层级 z 升序（渲染顺序）。 */
69	export function placementsOfScene(state: GalleryState, sceneId: string): Placement[] {
70	  return state.placements.filter((p) => p.sceneId === sceneId).sort((a, b) => a.z - b.z);
71	}
72	
73	// —— reducer ——
74	
75	export function galleryReducer(state: GalleryState, action: GalleryAction): GalleryState {
76	  switch (action.type) {
77	    case 'create-scene': {
78	      // 守卫：达上限、背景已被占用、或背景不存在 → 拒绝（背景不可重复、上限 3）。
79	      if (state.scenes.length >= MAX_SCENES) return state;
80	      const bg = BACKGROUNDS.find((b) => b.id === action.backgroundId);
81	      if (!bg) return state;
82	      if (state.scenes.some((s) => s.backgroundId === bg.id)) return state;
83	
84	      const scene: Scene = { id: newId('scene'), name: bg.name, backgroundId: bg.id };
85	      return { ...state, scenes: [...state.scenes, scene], activeSceneId: scene.id };
86	    }
87	
88	    case 'select-scene': {
89	      if (!state.scenes.some((s) => s.id === action.sceneId)) return state;
90	      if (state.activeSceneId === action.sceneId) return state;
91	      return { ...state, activeSceneId: action.sceneId };
92	    }
93	
94	    case 'rename-scene': {
95	      // 场景就地重命名（chip 点进去改）：只改 name，其余字段不动。空白名忽略（保底不产生空 chip）。
96	      const name = action.name.trim();
97	      if (!name) return state;
98	      const target = state.scenes.find((s) => s.id === action.sceneId);
99	      if (!target) return state;
100	      if (target.name === name) return state; // 无变化 → 免去一次全量落盘
101	      return {
102	        ...state,
103	        scenes: state.scenes.map((s) => (s.id === action.sceneId ? { ...s, name } : s)),
