111	      const target = state.scenes.find((s) => s.id === action.sceneId);
112	      if (!target) return state;
113	      const scenes = state.scenes.filter((s) => s.id !== action.sceneId);
114	      const placements = state.placements.filter((p) => p.sceneId !== action.sceneId);
115	      const activeSceneId =
116	        state.activeSceneId === action.sceneId
117	          ? scenes.length > 0
118	            ? scenes[0].id
119	            : null
120	          : state.activeSceneId;
121	      return { ...state, scenes, placements, activeSceneId };
122	    }
123	
124	    case 'set-mode': {
125	      if (state.mode === action.mode) return state;
126	      return { ...state, mode: action.mode };
127	    }
128	
129	    case 'place-item': {
130	      // 只在编辑模式、且有激活场景时把物件放入当前画布。
131	      if (state.mode !== 'edit') return state;
132	      const sceneId = state.activeSceneId;
133	      if (!sceneId) return state;
134	      if (!state.items.some((i) => i.id === action.itemId)) return state;
135	
136	      const n = state.placements.filter((p) => p.sceneId === sceneId).length;
137	      const rotations = [-5, 4, -3, 6, -6, 3];
138	      // N2（schema v3）：x/y 存物件**中心**在场景图坐标系内的百分比、w 存宽度占图宽的百分比。
139	      //  - 抽屉拖入：带落点坐标（x/y，已由上层换算成图内中心百分比）→ 落在指针放手处（允许出界进补边区）；
140	      //  - 点选放入：不带 → 走默认网格位（以中心百分比铺开，四列一行、留出四周呼吸区）。
